import sys

try:
    sys.set_int_max_str_digits(0)
except Exception:
    pass

try:
    sys.set_float_max_str_digits(0)
except Exception:
    pass


def parse_json(text: str) -> object:
    n = len(text)
    ws = ' \t\n\r'

    def skip_ws(i: int) -> int:
        while i < n and text[i] in ws:
            i += 1
        return i

    def hex4(i: int) -> tuple[int, int]:
        if i + 4 > n:
            raise ValueError

        h = 0
        for k in range(4):
            c = text[i + k]
            if '0' <= c <= '9':
                v = ord(c) - 48
            elif 'a' <= c <= 'f':
                v = ord(c) - 87
            elif 'A' <= c <= 'F':
                v = ord(c) - 55
            else:
                raise ValueError
            h = (h << 4) | v

        return h, i + 4

    def parse_string(i: int) -> tuple[str, int]:
        if i >= n or text[i] != '"':
            raise ValueError

        i += 1
        parts = []
        start = i

        while i < n:
            ch = text[i]

            if ch == '"':
                if start < i:
                    parts.append(text[start:i])
                return ''.join(parts), i + 1

            if ch == '\\':
                if start < i:
                    parts.append(text[start:i])

                i += 1
                if i >= n:
                    raise ValueError

                esc = text[i]
                i += 1

                if esc == 'u':
                    cp1, i = hex4(i)

                    if 0xD800 <= cp1 <= 0xDBFF:
                        if i + 2 > n:
                            raise ValueError
                        if text[i] != '\\':
                            raise ValueError
                        if text[i + 1] != 'u':
                            raise ValueError

                        cp2, i2 = hex4(i + 2)
                        if not (0xDC00 <= cp2 <= 0xDFFF):
                            raise ValueError

                        code = 0x10000 + ((cp1 - 0xD800) << 10) + (cp2 - 0xDC00)
                        parts.append(chr(code))
                        i = i2

                    elif 0xDC00 <= cp1 <= 0xDFFF:
                        raise ValueError
                    else:
                        parts.append(chr(cp1))

                    start = i

                elif esc == '"':
                    parts.append('"')
                    start = i
                elif esc == '\\':
                    parts.append('\\')
                    start = i
                elif esc == '/':
                    parts.append('/')
                    start = i
                elif esc == 'b':
                    parts.append('\b')
                    start = i
                elif esc == 'f':
                    parts.append('\f')
                    start = i
                elif esc == 'n':
                    parts.append('\n')
                    start = i
                elif esc == 'r':
                    parts.append('\r')
                    start = i
                elif esc == 't':
                    parts.append('\t')
                    start = i
                else:
                    raise ValueError

            else:
                o = ord(ch)
                if o < 0x20 or 0xD800 <= o <= 0xDFFF:
                    raise ValueError
                i += 1

        raise ValueError

    def parse_number(i: int) -> tuple[object, int]:
        start = i

        if i >= n:
            raise ValueError

        c = text[i]
        if c == '-':
            i += 1
            if i >= n:
                raise ValueError
            c = text[i]

        if not ('0' <= c <= '9'):
            raise ValueError

        if c == '0':
            i += 1
            if i < n and '0' <= text[i] <= '9':
                raise ValueError
        else:
            while i < n and '0' <= text[i] <= '9':
                i += 1

        has_float = False

        if i < n and text[i] == '.':
            has_float = True
            i += 1

            if i >= n or not ('0' <= text[i] <= '9'):
                raise ValueError

            while i < n and '0' <= text[i] <= '9':
                i += 1

        if i < n and (text[i] == 'e' or text[i] == 'E'):
            has_float = True
            i += 1

            if i < n and (text[i] == '+' or text[i] == '-'):
                i += 1

            if i >= n or not ('0' <= text[i] <= '9'):
                raise ValueError

            while i < n and '0' <= text[i] <= '9':
                i += 1

        token = text[start:i]

        if has_float:
            try:
                return float(token), i
            except OverflowError:
                if token[0] == '-':
                    return -float('inf'), i
                return float('inf'), i
            except ValueError:
                try:
                    import decimal
                    context = decimal.Context()
                    old_prec = context.prec
                    context.prec = max(1000, len(token) + 16)

                    value = decimal.Decimal(token)
                    context.prec = old_prec

                    return float(value), i
                except Exception:
                    raise ValueError

        return int(token), i

    def parse_value(i: int) -> tuple[object, int]:
        if i >= n:
            raise ValueError

        c = text[i]

        if c == '{':
            raise ValueError
        if c == '[':
            raise ValueError

        if c == '"':
            return parse_string(i)

        if c == 't':
            if text.startswith('true', i):
                return True, i + 4
        elif c == 'f':
            if text.startswith('false', i):
                return False, i + 5
        elif c == 'n':
            if text.startswith('null', i):
                return None, i + 4

        if c == '-' or ('0' <= c <= '9'):
            return parse_number(i)

        raise ValueError

    def assign_to_top(frame: list, value: object) -> None:
        if frame[0] == 0:
            frame[1].append(value)
        else:
            frame[1][frame[3]] = value
        frame[2] = 1

    i = skip_ws(0)
    if i >= n:
        raise ValueError

    final = None
    stack = []

    c = text[i]
    if c == '{':
        stack.append([1, {}, 0, None])
        i += 1
    elif c == '[':
        stack.append([0, [], 0, None])
        i += 1
    else:
        final, i = parse_value(i)

    while stack:
        frame = stack[-1]
        kind = frame[0]
        state = frame[2]

        i = skip_ws(i)
        if i >= n:
            raise ValueError

        c = text[i]

        if kind == 0:
            if state == 0:
                if c == ']':
                    completed = frame[1]
                    stack.pop()

                    if stack:
                        parent = stack[-1]
                        if parent[0] == 0:
                            parent[1].append(completed)
                        else:
                            parent[1][parent[3]] = completed
                        parent[2] = 1
                    else:
                        final = completed

                else:
                    value, i = parse_value(i)
                    frame[1].append(value)
                    frame[2] = 1

            elif state == 1:
                if c == ',':
                    i += 1
                    frame[2] = 2
                elif c == ']':
                    completed = frame[1]
                    stack.pop()

                    if stack:
                        parent = stack[-1]
                        if parent[0] == 0:
                            parent[1].append(completed)
                        else:
                            parent[1][parent[3]] = completed
                        parent[2] = 1
                    else:
                        final = completed

                else:
                    raise ValueError

            elif state == 2:
                value, i = parse_value(i)
                frame[1].append(value)
                frame[2] = 1

            else:
                raise ValueError

        else:
            if state == 0:
                if c == '}':
                    completed = frame[1]
                    stack.pop()

                    if stack:
                        parent = stack[-1]
                        if parent[0] == 0:
                            parent[1].append(completed)
                        else:
                            parent[1][parent[3]] = completed
                        parent[2] = 1
                    else:
                        final = completed

                else:
                    key, i = parse_string(i)
                    if key in frame[1]:
                        raise ValueError
                    frame[3] = key
                    frame[2] = 3

            elif state == 1:
                if c == ',':
                    i += 1
                    frame[2] = 2
                elif c == '}':
                    completed = frame[1]
                    stack.pop()

                    if stack:
                        parent = stack[-1]
                        if parent[0] == 0:
                            parent[1].append(completed)
                        else:
                            parent[1][parent[3]] = completed
                        parent[2] = 1
                    else:
                        final = completed

                else:
                    raise ValueError

            elif state == 2:
                key, i = parse_string(i)
                if key in frame[1]:
                    raise ValueError
                frame[3] = key
                frame[2] = 3

            elif state == 3:
                if c == ':':
                    i += 1
                    frame[2] = 4
                else:
                    raise ValueError

            elif state == 4:
                value, i = parse_value(i)
                frame[1][frame[3]] = value
                frame[2] = 1

            else:
                raise ValueError

    i = skip_ws(i)
    if i != n:
        raise ValueError

    return final
